// Validate Webhook Secret Authentication
const headers = $input.item.json.headers || {};
const authSecret = headers['x-bookleaf-secret'] || $input.item.json.body?.secret || '';
const EXPECTED_SECRET = 'bk_live_sec_9941a';

if (authSecret !== EXPECTED_SECRET) {
  throw new Error('401 Unauthorized: Invalid or missing x-bookleaf-secret header');
}

const body = $input.item.json.body || {};
const authorId = body.authorId || body.author_id;
const timestamp = Date.now();

if (!authorId) {
  throw new Error('400 Bad Request: authorId is required');
}

// Idempotency: Deduplicate calls within 60s
globalThis.__bookleaf_locks = globalThis.__bookleaf_locks || {};
const lastExecution = globalThis.__bookleaf_locks[authorId];
const isDuplicate = Boolean(lastExecution && (timestamp - lastExecution < 60000));

if (!isDuplicate) {
  globalThis.__bookleaf_locks[authorId] = timestamp;
}

return [{
  json: {
    isDuplicate,
    authorId,
    authorName: body.name || body.authorName || 'Author',
    authorEmail: body.email || body.authorEmail || 'author@bookleaf.com',
    city: body.city || 'India',
    books: body.books || [],
    totalEarned: body.totalRoyaltyEarned || 0,
    totalPaid: body.royaltyPaid || 0,
    totalPending: body.royaltyPending || 0,
    lastPayoutDate: body.lastPayoutDate || null,
    triggerType: body.triggerType || 'SINGLE',
    timestamp: new Date().toISOString()
  }
}];

