// Prepare RAG Grounding & Prompt for AI Model
const data = $json;

// Analyze books and edge cases
const publishedBooks = data.books.filter(b => b.status === 'Published & Live');
const inProductionBooks = data.books.filter(b => b.status !== 'Published & Live');
const isUnderThreshold = data.totalPending > 0 && data.totalPending < 1000;

// Knowledge Base Context
const policyContext = `
BOOKLEAF POLICY RULES FOR AI:
1. 80/20 Royalty Split: 80% net profit goes to author, 20% to BookLeaf.
2. Payout Schedule: Royalties are calculated quarterly and paid within 45 days of quarter ending.
3. Minimum Threshold: ₹1,000 minimum payout threshold. If accumulated pending royalties are below ₹1,000, they roll over to the next quarter.
4. In Production Pipeline: Books in Cover Design or Typesetting are actively being crafted. Reassure the author collaboratively.
5. Tone: Empathetic, transparent, encouraging, precise with numbers, no corporate fluff.
`;

const userPrompt = `Generate a personalized, warm, and highly professional royalty summary email for BookLeaf author ${data.authorName}.

AUTHOR FINANCIAL DATA:
- Author Name: ${data.authorName}
- Email: ${data.authorEmail}
- City: ${data.city}
- Published Titles (${publishedBooks.length}): ${publishedBooks.map(b => b.title + ' (ISBN: ' + b.isbn + ', Sold: ' + b.totalCopiesSold + ', Pending: ₹' + b.royaltyPending + ')').join('; ')}
- In-Production Titles (${inProductionBooks.length}): ${inProductionBooks.map(b => b.title + ' [Current Stage: ' + b.status + ']').join('; ')}
- Total Royalty Earned: ₹${data.totalEarned}
- Total Royalty Paid: ₹${data.totalPaid}
- Current Pending Royalty: ₹${data.totalPending}
- Last Payout Date: ${data.lastPayoutDate || 'None recorded'}
- Below ₹1,000 Threshold Rollover: ${isUnderThreshold ? 'YES (Current pending is ₹' + data.totalPending + ', under ₹1,000 threshold)' : 'NO'}

REQUIRED EMAIL STRUCTURE:
1. Warm personalized greeting to ${data.authorName.split(' ')[0]}.
2. High-level congratulatory note on catalog performance.
3. Transparent financial ledger (Earned, Paid, Pending).
4. Explanation of next payout timeline: explain quarterly cycle + 45-day window, or explain ₹1,000 rollover rule if balance is < ₹1,000.
5. Status update for any titles in production.
6. Clear support contact next steps and warm signoff from BookLeaf Operations Team.

Keep tone natural, encouraging, and mathematically accurate.`;

return [{
  json: {
    ...data,
    policyContext,
    userPrompt,
    inProductionCount: inProductionBooks.length,
    publishedCount: publishedBooks.length
  }
}];

// Parse AI Output with Robust Graceful Fallback
const item = $input.item.json;
const prev = $node["Build Grounded Prompt"].json;

let emailContent = '';
let isSuccess = false;
let errorMessage = '';

if (item.candidates && item.candidates[0]?.content?.parts?.[0]?.text) {
  emailContent = item.candidates[0].content.parts[0].text;
  isSuccess = true;
} else if (item.error) {
  errorMessage = item.error.message || 'AI API returned an error';
} else if (item.message) {
  errorMessage = item.message;
}

// Fallback Circuit Breaker: If AI failed or key missing, deterministic policy response
if (!isSuccess) {
  const firstName = prev.authorName.split(' ')[0];
  emailContent = `Dear ${firstName},\n\n` +
    `Here is your BookLeaf publishing royalty statement summary:\n\n` +
    `• Total Royalty Earned to Date: ₹${prev.totalEarned.toLocaleString()}\n` +
    `• Total Royalty Disbursed: ₹${prev.totalPaid.toLocaleString()}\n` +
    `• Current Pending Royalty Balance: ₹${prev.totalPending.toLocaleString()}\n\n` +
    (prev.totalPending >= 1000 
      ? `Your pending royalty balance exceeds the ₹1,000 threshold and is scheduled for disbursement within the standard 45-day post-quarter payout cycle via bank transfer.\n\n`
      : prev.totalPending > 0
      ? `Under BookLeaf payout policy, balances under ₹1,000 roll over to the upcoming quarter.\n\n`
      : `Your account is fully settled with zero pending dues. Thank you for publishing with us!\n\n`) +
    `Warm regards,\nBookLeaf Author Operations Desk`;

  isSuccess = true;
  errorMessage = 'Generated via Deterministic Fallback Circuit Breaker';
}

return [{
  json: {
    authorId: prev.authorId,
    authorName: prev.authorName,
    authorEmail: prev.authorEmail,
    triggerType: prev.triggerType,
    status: isSuccess ? 'SUCCESS' : 'FAILED',
    emailContent,
    errorMessage,
    processedAt: new Date().toISOString()
  }
}];
